function isWebGPUAvailable() {
  return typeof navigator !== "undefined" && "gpu" in navigator;
}
function isWebGLBackend(renderer) {
  const backend = renderer.backend;
  if (backend) {
    const constructorName = backend.constructor?.name;
    if (constructorName === "WebGLBackend") {
      return true;
    }
    if (constructorName === "WebGPUBackend") {
      return false;
    }
  }
  return !isWebGPUAvailable();
}
function createWaveSimulation(renderer, options) {
  const useWebGL = options.forceBackend === "webgl" || options.forceBackend !== "webgpu" && isWebGLBackend(renderer);
  if (useWebGL) {
    return new WebGLWaveSimulation(renderer, {
      waveUniforms: options.waveUniforms,
      foamWindBias: options.foamWindBias,
      cascades: options.cascades,
      qualityConfig: options.qualityConfig
    });
  } else {
    return new WebGPUWaveSimulation(renderer, {
      waveUniforms: options.waveUniforms,
      foamWindBias: options.foamWindBias,
      cascades: options.cascades,
      qualityConfig: options.qualityConfig
    });
  }
}

