  // Calculate distance from center (0.5, 0.5)
  const center = uvCoord.sub(0.5);
  const dist = center.length();

  // Create vignette gradient
  // Larger radius = larger clear area in center (vignette starts further out)
  // Distance from center ranges from 0 (center) to ~0.707 (corners)
  const vignetteStart = settings.vignetteRadius.mul(0.5);
