class Lights {
  static lightDir = new Vector3(0, 300, 0).multiplyScalar(-1).normalize()

  constructor() {
    this.object = new Object3D();

    this.directionalLight = new DirectionalLight(0xffffff, 2.0);
    this.directionalLight.position.set(100, 300, 0);
    this.object.add(this.directionalLight);

    this.ambientLight = new HemisphereLight(
      0xffffff,
      new Color(0.1, 0.4, 0.9),
      1
    );
    this.object.add(this.ambientLight);
  }

  setupTheatreControls(theatreSheet) {
    if (!theatreSheet) return

    const dl = this.directionalLight;

    this._theatreObject = theatreSheet.object(
      'Lights / Directional',
      {
        intensity: distExports.types.number(dl.intensity, {
          range: [0, 10],
          precision: 0.01
        }),
        color: distExports.types.rgba({ r: 1, g: 1, b: 1, a: 1 }),
        positionX: distExports.types.number(dl.position.x, {
          range: [-500, 500],
          precision: 1
        }),
        positionY: distExports.types.number(dl.position.y, {
          range: [-500, 500],
          precision: 1
        }),
        positionZ: distExports.types.number(dl.position.z, {
          range: [-500, 500],
          precision: 1
        })
      },
      { reconfigure: true }
    );

    this._theatreObject.onValuesChange((v) => {
      dl.intensity = v.intensity;
      dl.color.setRGB(v.color.r, v.color.g, v.color.b);
      dl.position.set(v.positionX, v.positionY, v.positionZ);
    });
  }

  update(_elapsed) {}
}

