  async setupSpotlight() {
    this.spotlight = new SpotLight(16777215, 100);
    this.spotlight.position.set(0, 5, 0);
    this.spotlight.angle = Math.PI / 6;
    this.spotlight.penumbra = 0.1;
    this.spotlight.decay = 2;
    this.spotlight.distance = 20;
    this.spotlight.shadow.mapSize.width = 1024;
    this.spotlight.shadow.mapSize.height = 1024;
    this.spotlight.shadow.camera.near = 0.5;
    this.spotlight.shadow.camera.far = 50;
    this.spotlight.shadow.bias = -0.01;
    this.scene.add(this.spotlight);
    this.scene.add(this.spotlight.target);
    const renderer = store.multiScene.renderer;
    this.causticsRenderTarget = new CausticsRenderTarget(
      renderer,
      store.isMobile ? 256 : 512,
      this.spotlight
    );
    this.causticsRenderTarget.updateScale(2.5);
    this.setupSpotlightControls();
  }
  setupSpotlightControls() {
    if (!this.theatreSheet || !this.spotlight) return;
    const hexToRgba = (hex) => {
      const r = (hex >> 16 & 255) / 255;
      const g = (hex >> 8 & 255) / 255;
      const b = (hex & 255) / 255;
      return { r, g, b, a: 1 };
    };
    this.spotlightObject = this.theatreSheet.object(
      "Lights / Spotlight - Caustics",
      {
        intensity: distExports.types.number(this.spotlight.intensity, {
          range: [0, 5e3],
          precision: 0.01
        }),
        color: distExports.types.rgba(hexToRgba(this.spotlight.color.getHex())),
        positionX: distExports.types.number(this.spotlight.position.x, {
          range: [-20, 20],
          precision: 0.01
        }),
        positionY: distExports.types.number(this.spotlight.position.y, {
          range: [-20, 20],
          precision: 0.01
        }),
        positionZ: distExports.types.number(this.spotlight.position.z, {
          range: [-20, 20],
          precision: 0.01
        }),
        targetX: distExports.types.number(this.spotlight.target.position.x, {
          range: [-20, 20],
          precision: 0.01
        }),
        targetY: distExports.types.number(this.spotlight.target.position.y, {
          range: [-20, 20],
          precision: 0.01
        }),
        targetZ: distExports.types.number(this.spotlight.target.position.z, {
          range: [-20, 20],
          precision: 0.01
        }),
        angle: distExports.types.number(this.spotlight.angle, {
          range: [0, Math.PI / 2],
          precision: 0.01
        }),
        penumbra: distExports.types.number(this.spotlight.penumbra, {
          range: [0, 1],
          precision: 0.01
        }),
        decay: distExports.types.number(this.spotlight.decay, {
          range: [0, 5],
          precision: 0.01
        }),
        distance: distExports.types.number(this.spotlight.distance, {
          range: [0, 100],
          precision: 0.01
        })
      },
      { reconfigure: true }
    );
    this.spotlightObject.onValuesChange((values) => {
      this.spotlight.intensity = values.intensity;
      this.spotlight.color.setRGB(values.color.r, values.color.g, values.color.b).convertSRGBToLinear();
      this.spotlight.position.set(
        values.positionX,
        values.positionY,
        values.positionZ
      );
      this.spotlight.target.position.set(
        values.targetX,
        values.targetY,
        values.targetZ
      );
      this.spotlight.angle = values.angle;
      this.spotlight.penumbra = values.penumbra;
      this.spotlight.decay = values.decay;
      this.spotlight.distance = values.distance;
    });
  }
  async setupGodray() {
    this.godray = createGodray({
      position: [0, -2, 0],
      rotation: [0, 0, 0],
      color: "#88ccff",
      opacity: 0.3,
      topRadius: 3,
      bottomRadius: 2,
      height: 10,
      timeSpeed: 0.1,
      noiseScale: 5,
      smoothBottom: 0.1,
      smoothTop: 0.9,
      fresnelPower: 5
    });
    if (this.godray && this.godray.mesh) {
      this.scene.add(this.godray.mesh);
      if (this.godray.debugMesh) {
        this.scene.add(this.godray.debugMesh);
      }
      this.setupGodrayControls();
    }
  }
  setupGodrayControls() {
    if (!this.theatreSheet || !this.godray) {
      return;
    }
    this.godrayTheatre = createGodrayTheatre({
      sheet: this.theatreSheet,
      key: "Godray",
      settings: this.godray.state,
      godray: this.godray,
      onChange: (newSettings) => {
      }
    });
  }
